import heapq, math
from itertools import combinations

def route_postman(skel, neighbors):
 pts=list(zip(*__import__('numpy').where(skel)))
 adj={p:neighbors(p,skel) for p in pts}
 # shortest paths from each odd node; weighted Euclidean
 odds=[p for p in pts if len(adj[p])%2]
 if odds:
  dist={}; prev={}
  for src in odds:
   D={src:0.}; P={}; Q=[(0.,src)]; seen=set()
   while Q:
    d,p=heapq.heappop(Q)
    if p in seen:continue
    seen.add(p)
    for q in adj[p]:
     nd=d+math.hypot(q[0]-p[0],q[1]-p[1])
     if nd<D.get(q,float('inf')):
      D[q]=nd;P[q]=p;heapq.heappush(Q,(nd,q))
   dist[src]=D;prev[src]=P
  best=(float('inf'),None)
  def pair_cost(arr):
   if not arr:return (0.,[])
   a=arr[0];ans=(float('inf'),None)
   for i in range(1,len(arr)):
    v=arr[i]
    c,pp=pair_cost(arr[1:i]+arr[i+1:])
    c+=dist[a][v]
    if c<ans[0]:ans=(c,[(a,v)]+pp)
   return ans
  if len(odds)>=2:
   for i,j in combinations(range(len(odds)),2):
    leftover=odds[:i]+odds[i+1:j]+odds[j+1:]
    c,pairs=pair_cost(leftover)
    if c<best[0]:best=(c,(odds[i],odds[j],pairs))
   start,end,pairs=best[1]
  else:start=end=odds[0];pairs=[]
  # multiedge counts keyed by undirected edge
  ec={}
  def key(a,b):return tuple(sorted((a,b)))
  for a in pts:
   for b in adj[a]:
    if a<b:ec[key(a,b)]=1
  for a,b in pairs:
   cur=b; rev=[b]
   while cur!=a:
    cur=prev[a][cur];rev.append(cur)
   for x,y in zip(rev,rev[1:]):ec[key(x,y)]+=1
 else:
  start=min(pts);end=start;ec={}
  for a in pts:
   for b in adj[a]:
    if a<b:ec[tuple(sorted((a,b)))]=1
 # Euler trail over multigraph
 mg={p:[] for p in pts};eid=0
 for (a,b),count in ec.items():
  for _ in range(count):mg[a].append((b,eid));mg[b].append((a,eid));eid+=1
 used=set();st=[start];out=[]
 while st:
  v=st[-1]
  while mg[v] and mg[v][-1][1] in used:mg[v].pop()
  if mg[v]:
   w,e=mg[v].pop();used.add(e);st.append(w)
  else:out.append(st.pop())
 out=out[::-1]
 return out,odds,ec,start,end
